edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles every bounce:
// the walls, the paddle AND the bricks (#1). Sub-steps the move so the ball can
// never tunnel/jump across a brick between two discrete position checks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball } = state;

  // Sweep the movement: break `dt` into sub-steps small enough that the ball
  // cannot cross a brick in a single leap (tunnelling, #1). Each sub-step is
  // far below the ball radius, so any brick that is grazed is actually hit.
  const maxStep = 2; // px per sub-step
  const travel = Math.hypot(ball.vx * dt, ball.vy * dt);
  const subSteps = Math.max(1, Math.ceil(travel / maxStep));
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    moveBallAndBounce(state, subDt);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// Advances the ball one tiny sub-step and applies wall, ceiling, paddle and
// brick bounces. Keeping each sub-step small is what prevents tunnelling (#1).
function moveBallAndBounce(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  resolveBricks(state);
}

// ----------------------- Brick collision (#1) ------------------------------

// The ball only ever touches bricks that share an edge (its diameter is 14 px
// against an 8 px gap), so a set of overlapping bricks is always a contiguous
// blob. Resolving that blob as a SINGLE solid surface makes the bounce apply
// exactly once: flipping vy twice (once per neighbour) would cancel out and
// the ball would punch straight through the seam.
function resolveBricks(state) {
  const { ball } = state;

  const hit = [];
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      hit.push(brick);
      if (brick.x < minX) minX = brick.x;
      if (brick.y < minY) minY = brick.y;
      if (brick.x + brick.w > maxX) maxX = brick.x + brick.w;
      if (brick.y + brick.h > maxY) maxY = brick.y + brick.h;
    }
  }
  if (hit.length === 0) return;

  // The combined bounding surface of every brick touched this sub-step.
  const box = { x: minX, y: minY, w: maxX - minX, h: maxY - minY };

  // Penetration depth on each axis (how deep the ball is inside the surface).
  const rightOverlap = ball.x + ball.r - box.x;
  const leftOverlap = box.x + box.w - (ball.x - ball.r);
  const topOverlap = ball.y + ball.r - box.y;
  const bottomOverlap = box.y + box.h - (ball.y - ball.r);
  const penX = Math.min(rightOverlap, leftOverlap);
  const penY = Math.min(topOverlap, bottomOverlap);

  // Which side of the surface the ball is travelling out of.
  const fromLeft = rightOverlap <= leftOverlap; // ball center left of box
  const fromTop = topOverlap <= bottomOverlap; // ball center above box

  if (Math.abs(penX - penY) < 0.0001) {
    // Diagonal / corner hit: equal penetrations -> flip BOTH components and
    // push the ball out toward the corner.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = fromLeft ? box.x - ball.r : box.x + box.w + ball.r;
    ball.y = fromTop ? box.y - ball.r : box.y + box.h + ball.r;
  } else if (penY < penX) {
    // Vertical (top/bottom) hit: flip vy, leave vx exactly as it was, push out.
    ball.vy = -ball.vy;
    ball.y = fromTop ? box.y - ball.r : box.y + box.h + ball.r;
  } else {
    // Horizontal (left/right) hit: flip vx, leave vy exactly as it was, push out.
    ball.vx = -ball.vx;
    ball.x = fromLeft ? box.x - ball.r : box.x + box.w + ball.r;
  }

  // Destroy every brick we hit and credit the score / combo.
  for (const brick of hit) {
    if (!brick.alive) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }
}

